  $("open-rename-profile").addEventListener("click",()=>{const profile=selectedProfile(),isDefault=profileName(profile)==="default";$("rename-dialog-title").textContent=isDefault?"Rename default profile":"Rename profile";$("rename-dialog-copy").textContent=isDefault?"The built-in ID remains “default”; this changes its display name.":`Rename ${profileLabel(profile)} everywhere Hermes references it.`;$("rename-profile-name").value=isDefault?(profile.display_name||""):profileName(profile);openDialog("rename-profile-dialog")});$("rename-profile-submit").addEventListener("click",renameProfile);
  $("open-export-profile").addEventListener("click",()=>{$("export-output-path").value="";$("export-extra-files").replaceChildren();$("export-result").hidden=true;openDialog("export-profile-dialog")});$("add-export-file").addEventListener("click",()=>$("export-extra-files").append(createExtraFileRow()));$("export-profile-submit").addEventListener("click",exportProfile);$("copy-export-path").addEventListener("click",()=>copyText($("export-result-path").textContent));$("open-import-profile").addEventListener("click",()=>openDialog("import-profile-dialog"));$("import-profile-submit").addEventListener("click",importProfile);
